import { createGraph, rankNodes } from 'graphRAG';

export function entityRelationshipSynthesis(agentOutputs) {
  const graph = createGraph();
  agentOutputs.forEach(output => {
    output.entities.forEach(entity => {
      graph.addNode(entity.name, entity.attributes);
      entity.relationships.forEach(rel => {
        graph.addEdge(entity.name, rel.target, rel.type);
      });
    });
  });
  return rankNodes(graph);
}